151	<script>
152	(function () {
153	  "use strict";
154	
155	  var ROWS = 20;
156	  var COLS = 10;
157	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
158	
159	  // Spawn shapes as [row, col] offsets. Top row of every shape is row 0.
160	  var SHAPES = {
161	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
162	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
163	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
164	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
165	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
166	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
167	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
168	  };
169	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
170	
171	  // The I piece has its own rotation states so it turns in place like the
172	  // guideline piece, without ever reaching above the piece's own row.
173	  var I_STATES = [
174	    [[0, 0], [0, 1], [0, 2], [0, 3]],
175	    [[0, 2], [1, 2], [2, 2], [3, 2]],
176	    [[1, 0], [1, 1], [1, 2], [1, 3]],
177	    [[0, 1], [1, 1], [2, 1], [3, 1]]
178	  ];
179	  // Sideways shifts tried, in order, when a rotated shape does not fit.
180	  var KICKS = [0, -1, 1, -2, 2];
181	
182	  // Locking rule.
183	  var LOCK_DELAY = 2;      // gravity ticks a piece may spend unable to fall
184	  var MAX_LOCK_RESETS = 3; // times a piece may restart its lock delay
185	
186	  // Scoring rule. Points for a clear depend on how many rows go at once, times
187	  // the current level. The table grows faster than the row count, so clearing
188	  // rows together always beats clearing the same rows one at a time.
189	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
190	  var SOFT_DROP_POINTS = 1; // per cell moved down by the player
191	  var HARD_DROP_POINTS = 2; // per cell dropped
192	
193	  // ---- State ----
194	  var board;       // ROWS x COLS array of piece letters or null
195	  var current;     // { type, row, col, rot, shape, lockTicks, lockResets } or null
196	  var queue;       // upcoming piece letters, soonest first
197	  var bag;         // 7-bag for the random generator
198	  var score, level, lines, status;
199	  var timer = null;
200	
201	  function emptyBoard() {
202	    var b = [];
203	    for (var r = 0; r < ROWS; r++) {
204	      var row = [];
205	      for (var c = 0; c < COLS; c++) row.push(null);
206	      b.push(row);
207	    }
208	    return b;
209	  }
210	
211	  function randomPiece() {
212	    if (!bag || bag.length === 0) {
213	      bag = TYPES.slice();
214	      for (var i = bag.length - 1; i > 0; i--) {
215	        var j = Math.floor(Math.random() * (i + 1));
216	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
217	      }
218	    }
219	    return bag.pop();
220	  }
221	
222	  function sanitizeQueue(q) {
223	    if (!Array.isArray(q)) return [];
224	    return q.map(function (x) { return String(x).toUpperCase(); })
225	            .filter(function (x) { return TYPES.indexOf(x) !== -1; });
226	  }
227	
228	  // Keep at least the next piece queued for the preview.
229	  var PREVIEW_COUNT = 1;
230	  function fillQueue() {
231	    while (queue.length < PREVIEW_COUNT) queue.push(randomPiece());
232	  }
233	
234	  function pieceCells(p, dRow, dCol) {
235	    var out = [];
236	    for (var i = 0; i < p.shape.length; i++) {
237	      out.push([p.row + p.shape[i][0] + (dRow || 0), p.col + p.shape[i][1] + (dCol || 0)]);
238	    }
239	    return out;
240	  }
241	
242	  function fits(p, dRow, dCol) {
243	    var cells = pieceCells(p, dRow, dCol);
244	    for (var i = 0; i < cells.length; i++) {
245	      var r = cells[i][0], c = cells[i][1];
246	      if (c < 0 || c >= COLS || r >= ROWS) return false;
247	      if (r >= 0 && board[r][c]) return false;
248	    }
249	    return true;
250	  }
251	
252	  function spawn() {
253	    fillQueue();
254	    var type = queue.shift();
255	    fillQueue();
256	    var p = {
257	      type: type, row: 0, col: SPAWN_COL[type], rot: 0, shape: SHAPES[type],
258	      lockTicks: 0, lockResets: 0
259	    };
260	    if (!fits(p, 0, 0)) {
261	      current = null;
262	      status = "gameover";
263	      stopTimer();
264	      return;
265	    }
266	    current = p;
267	  }
268	
269	  function lock() {
270	    var cells = pieceCells(current, 0, 0);
271	    for (var i = 0; i < cells.length; i++) {
272	      var r = cells[i][0], c = cells[i][1];
273	      if (r >= 0 && r < ROWS && c >= 0 && c < COLS) board[r][c] = current.type;
274	    }
275	    current = null;
276	    clearLines();
277	    spawn();
278	  }
279	
280	  // Remove every full row; everything above drops down to fill the gap.
281	  function clearLines() {
282	    var kept = board.filter(function (row) {
283	      return row.some(function (v) { return !v; });
284	    });
285	    var cleared = ROWS - kept.length;
286	    if (cleared === 0) return;
287	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
288	    board = kept;
289	    lines += cleared;
290	    score += CLEAR_POINTS[cleared] * level;
291	  }
292	
293	  // One gravity step. The real timer, tick() and a falling soft drop run this.
294	  // If the piece cannot fall, the step counts one tick of lock delay instead.
295	  // Returns true if the piece moved down.
296	  function gravityStep() {
297	    if (status !== "running" || !current) return false;
298	    if (fits(current, 1, 0)) {
299	      current.row += 1;
300	      current.lockTicks = 0;
301	      return true;
302	    }
303	    current.lockTicks += 1;
304	    if (current.lockTicks >= LOCK_DELAY) lock();
305	    return false;
306	  }
307	
308	  // Player input on a resting piece restarts the lock delay, up to
309	  // MAX_LOCK_RESETS times per piece.
310	  function restartLockDelay() {
311	    if (current.lockResets < MAX_LOCK_RESETS) {
312	      current.lockResets += 1;
313	      current.lockTicks = 0;
314	    }
315	  }
316	
317	  // On a resting piece, soft drop acts like a sideways move: it restarts the
318	  // lock delay and never counts toward locking. It scores nothing there,
319	  // because the piece does not move.
320	  function softDrop() {
321	    if (status !== "running" || !current) return;
322	    if (!fits(current, 1, 0)) {
323	      restartLockDelay();
324	      return;
325	    }
326	    if (gravityStep()) score += SOFT_DROP_POINTS;
327	  }
328	
329	  function move(dCol) {
330	    if (status !== "running" || !current) return;
331	    if (!fits(current, 0, dCol)) return;
332	    var resting = !fits(current, 1, 0);
333	    current.col += dCol;
334	    if (resting) restartLockDelay();
335	  }
336	
337	  function rotatedShape(p) {
338	    var rot = (p.rot + 1) % 4;
339	    if (p.type === "I") return { rot: rot, shape: I_STATES[rot] };
340	    var size = p.type === "O" ? 2 : 3;
341	    return {
342	      rot: rot,
343	      shape: p.shape.map(function (off) { return [off[1], size - 1 - off[0]]; })
344	    };
345	  }
346	
347	  // Rotate clockwise. If the turned shape does not fit, try shifting it
348	  // sideways; if nothing fits, leave the piece exactly as it was.
349	  function rotateCW() {
350	    if (status !== "running" || !current) return;
351	    var next = rotatedShape(current);
352	    var trial = { row: current.row, col: current.col, shape: next.shape };
353	    for (var i = 0; i < KICKS.length; i++) {
354	      if (fits(trial, 0, KICKS[i])) {
355	        current.col += KICKS[i];
356	        current.rot = next.rot;
357	        current.shape = next.shape;
358	        return;
359	      }
360	    }
361	  }
362	
363	  function hardDrop() {
364	    if (status !== "running" || !current) return;
365	    while (fits(current, 1, 0)) {
366	      current.row += 1;
367	      score += HARD_DROP_POINTS;
368	    }
369	    lock();
370	  }
371	
372	  var ACTIONS = {
373	    left: function () { move(-1); },
374	    right: function () { move(1); },
375	    rotateCW: rotateCW,
376	    softDrop: softDrop,
377	    hardDrop: hardDrop
378	  };
379	
380	  // ---- Timer ----
381	  function gravityInterval() {
382	    return Math.max(100, 1000 - (level - 1) * 100);
383	  }
384	
385	  function onTimer() {
386	    gravityStep();
387	    render();
388	  }
389	
390	  function startTimer() {
391	    stopTimer();
392	    timer = setInterval(onTimer, gravityInterval());
393	  }
394	
395	  function stopTimer() {
396	    if (timer !== null) {
397	      clearInterval(timer);
398	      timer = null;
399	    }
400	  }
401	
402	  // ---- Rendering (synchronous) ----
403	  var boardEl = document.getElementById("board");
404	  var overlayEl = document.getElementById("overlay");
405	  var scoreEl = document.getElementById("score");
406	  var levelEl = document.getElementById("level");
407	  var linesEl = document.getElementById("lines");
408	  var previewEl = document.getElementById("preview");
409	  var cellEls = [];
410	  var previewItems = []; // [{ el, cells }] one per upcoming piece
411	
412	  (function buildDom() {
413	    for (var r = 0; r < ROWS; r++) {
414	      var row = [];
415	      for (var c = 0; c < COLS; c++) {
416	        var el = document.createElement("div");
417	        el.className = "cell";
418	        el.setAttribute("data-testid", "cell");
419	        el.setAttribute("data-row", String(r));
420	        el.setAttribute("data-col", String(c));
421	        el.setAttribute("data-filled", "false");
422	        el.setAttribute("data-piece", "");
423	        boardEl.insertBefore(el, overlayEl);
424	        row.push(el);
425	      }
426	      cellEls.push(row);
427	    }
428	    for (var i = 0; i < PREVIEW_COUNT; i++) {
429	      var item = document.createElement("div");
430	      item.className = "preview-item";
431	      item.setAttribute("data-testid", "next-piece-item");
432	      item.setAttribute("data-piece", "");
433	      var minis = [];
434	      for (var k = 0; k < 8; k++) {
435	        var m = document.createElement("div");
436	        m.className = "mini";
437	        item.appendChild(m);
438	        minis.push(m);
439	      }
440	      previewEl.appendChild(item);
441	      previewItems.push({ el: item, cells: minis });
442	    }
443	  })();
444	
445	  function setCell(el, type) {
446	    var piece = type || "";
447	    if (el.getAttribute("data-piece") === piece) return;
448	    el.className = piece ? "cell p-" + piece : "cell";
449	    el.setAttribute("data-filled", piece ? "true" : "false");
450	    el.setAttribute("data-piece", piece);
451	  }
452	
453	  function render() {
454	    var view = board.map(function (row) { return row.slice(); });
455	    if (current) {
456	      var cells = pieceCells(current, 0, 0);
457	      for (var i = 0; i < cells.length; i++) {
458	        var r = cells[i][0], c = cells[i][1];
459	        if (r >= 0 && r < ROWS && c >= 0 && c < COLS) view[r][c] = current.type;
460	      }
461	    }
462	    for (var rr = 0; rr < ROWS; rr++) {
463	      for (var cc = 0; cc < COLS; cc++) setCell(cellEls[rr][cc], view[rr][cc]);
464	    }
465	
466	    scoreEl.textContent = String(score);
467	    levelEl.textContent = String(level);
468	    linesEl.textContent = String(lines);
469	
470	    previewItems.forEach(function (item, idx) {
471	      var type = queue[idx] || "";
472	      item.el.setAttribute("data-piece", type);
473	      item.el.hidden = !type;
474	      for (var k = 0; k < item.cells.length; k++) item.cells[k].className = "mini";
475	      if (type) {
476	        SHAPES[type].forEach(function (off) {
477	          item.cells[off[0] * 4 + off[1]].className = "mini p-" + type;
478	        });
479	      }
480	    });
481	
482	    overlayEl.hidden = status !== "gameover";
483	  }
484	
485	  // ---- Game control ----
486	  function newGame(q) {
487	    board = emptyBoard();
488	    bag = [];
489	    queue = sanitizeQueue(q);
490	    score = 0;
491	    level = 1;
492	    lines = 0;
493	    status = "running";
494	    current = null;
495	    spawn();
496	    if (status === "running") startTimer();
497	    render();
498	  }
499	
500	  function parseRows(rows) {
501	    var b = emptyBoard();
502	    if (!Array.isArray(rows)) return b;
503	    for (var r = 0; r < ROWS && r < rows.length; r++) {
504	      var line = String(rows[r]);
505	      for (var c = 0; c < COLS && c < line.length; c++) {
506	        var ch = line.charAt(c).toUpperCase();
507	        b[r][c] = TYPES.indexOf(ch) !== -1 ? ch : null;
508	      }
509	    }
510	    return b;
511	  }
512	
513	  function boardToRows() {
514	    return board.map(function (row) {
515	      return row.map(function (v) { return v || "."; }).join("");
516	    });
517	  }
518	
519	  // ---- Keyboard ----
520	  var KEYS = {
521	    ArrowLeft: "left",
522	    ArrowRight: "right",
523	    ArrowUp: "rotateCW",
524	    x: "rotateCW",
525	    X: "rotateCW",
526	    ArrowDown: "softDrop",
527	    " ": "hardDrop",
528	    Spacebar: "hardDrop"
529	  };
530	
531	  document.addEventListener("keydown", function (e) {
532	    if (status === "gameover" && e.key === "Enter") {
533	      e.preventDefault();
534	      newGame();
535	      return;
536	    }
537	    var action = KEYS[e.key];
538	    if (!action) return;
539	    e.preventDefault();
540	    ACTIONS[action]();
541	    render();
542	  });
543	
544	  document.getElementById("restart").addEventListener("click", function () {
545	    newGame();
546	  });
547	
548	  // ---- Test control surface ----
549	  window.__tetris = {
550	    newGame: function (q) { newGame(q); },
551	    setQueue: function (q) {
552	      queue = sanitizeQueue(q);
